import java.util.*;
import java.time.Instant;

enum OrderStatus {
    PLACED, CONFIRMED, PREPARING, READY, ASSIGNED,
    PICKED_UP, DELIVERED, CANCELLED;

    // Legal transitions: from → set of allowed `to` states
    private static final Map<OrderStatus, Set<OrderStatus>> TRANSITIONS = Map.of(
        PLACED,    Set.of(CONFIRMED, CANCELLED),
        CONFIRMED, Set.of(PREPARING, CANCELLED),
        PREPARING, Set.of(READY, CANCELLED),
        READY,     Set.of(ASSIGNED, CANCELLED),
        ASSIGNED,  Set.of(PICKED_UP, CANCELLED),
        PICKED_UP, Set.of(DELIVERED),
        DELIVERED, Set.of(),
        CANCELLED, Set.of()
    );

    public boolean canTransitionTo(OrderStatus next) {
        return TRANSITIONS.getOrDefault(this, Set.of()).contains(next);
    }
}

enum AgentStatus { AVAILABLE, BUSY, OFFLINE }

record GeoLocation(double lat, double lng) {}
record OrderItem(String menuItemId, String name, long price, int quantity) {}
record MenuItem(String itemId, String name, long price, boolean available) {}

class Order {
    private final String orderId;
    private final String customerId;
    private final String restaurantId;
    private final List<OrderItem> items;
    private final long totalAmount;
    private volatile OrderStatus status = OrderStatus.PLACED;
    private volatile String deliveryAgentId;
    private final Set<String> rejectedAgents = ConcurrentHashMap.newKeySet();
    private final Instant createdAt = Instant.now();

    public Order(String customerId, String restaurantId,
                 List<OrderItem> items, long total) {
        this.orderId = UUID.randomUUID().toString();
        this.customerId = customerId;
        this.restaurantId = restaurantId;
        this.items = List.copyOf(items);
        this.totalAmount = total;
    }

    public synchronized void transitionTo(OrderStatus next) {
        if (!status.canTransitionTo(next))
            throw new InvalidStateTransitionException(
                status + " → " + next + " is not allowed");
        this.status = next;
    }

    public synchronized void assignAgent(String agentId) {
        if (status != OrderStatus.READY && status != OrderStatus.ASSIGNED)
            throw new IllegalStateException(
                "Cannot assign agent in status " + status);
        this.deliveryAgentId = agentId;
        if (status == OrderStatus.READY) transitionTo(OrderStatus.ASSIGNED);
    }

    public void addRejectedAgent(String agentId) { rejectedAgents.add(agentId); }

    public String getOrderId()     { return orderId; }
    public String getCustomerId()  { return customerId; }
    public String getRestaurantId() { return restaurantId; }
    public OrderStatus getStatus() { return status; }
    public String getDeliveryAgentId() { return deliveryAgentId; }
    public Set<String> getRejectedAgents() { return rejectedAgents; }
    public long getTotalAmount() { return totalAmount; }
}

class DeliveryAgent {
    private final String agentId;
    private final String name;
    private volatile GeoLocation currentLocation;
    private volatile AgentStatus status = AgentStatus.AVAILABLE;

    public DeliveryAgent(String agentId, String name, GeoLocation loc) {
        this.agentId = agentId;
        this.name = name;
        this.currentLocation = loc;
    }

    public synchronized void markBusy() { status = AgentStatus.BUSY; }
    public synchronized void markAvailable() { status = AgentStatus.AVAILABLE; }
    public synchronized void markOffline() { status = AgentStatus.OFFLINE; }
    public void updateLocation(GeoLocation loc) { this.currentLocation = loc; }
    public boolean isAvailable() { return status == AgentStatus.AVAILABLE; }

    public String getAgentId() { return agentId; }
    public GeoLocation getCurrentLocation() { return currentLocation; }
}

interface DispatchStrategy {
    Optional<DeliveryAgent> selectAgent(GeoLocation pickupLocation,
                                         Collection<DeliveryAgent> candidates);
}

class NearestAgentStrategy implements DispatchStrategy {
    @Override
    public Optional<DeliveryAgent> selectAgent(GeoLocation pickup,
                                                Collection<DeliveryAgent> candidates) {
        return candidates.stream()
            .filter(DeliveryAgent::isAvailable)
            .min(Comparator.comparingDouble(
                a -> haversineKm(pickup, a.getCurrentLocation())));
    }

    static double haversineKm(GeoLocation a, GeoLocation b) {
        final double R = 6371; // earth radius in km
        double dLat = Math.toRadians(b.lat() - a.lat());
        double dLng = Math.toRadians(b.lng() - a.lng());
        double sinLat = Math.sin(dLat / 2);
        double sinLng = Math.sin(dLng / 2);
        double c = sinLat * sinLat
            + Math.cos(Math.toRadians(a.lat())) * Math.cos(Math.toRadians(b.lat()))
            * sinLng * sinLng;
        return 2 * R * Math.atan2(Math.sqrt(c), Math.sqrt(1 - c));
    }
}

class DeliveryAgentService {
    private final ConcurrentHashMap<String, DeliveryAgent> agents = new ConcurrentHashMap<>();
    private final DispatchStrategy strategy;

    public DeliveryAgentService(DispatchStrategy strategy) {
        this.strategy = strategy;
    }

    public void register(DeliveryAgent agent) {
        agents.put(agent.getAgentId(), agent);
    }

    // Find an agent for an order, excluding those who already rejected
    public Optional<DeliveryAgent> findAgentForOrder(
            GeoLocation pickup, Set<String> excludeIds) {
        List<DeliveryAgent> candidates = agents.values().stream()
            .filter(a -> !excludeIds.contains(a.getAgentId()))
            .toList();
        return strategy.selectAgent(pickup, candidates);
    }

    public void updateLocation(String agentId, GeoLocation loc) {
        DeliveryAgent a = agents.get(agentId);
        if (a != null) a.updateLocation(loc);
    }

    public DeliveryAgent get(String agentId) { return agents.get(agentId); }
}

class OrderService {
    private final ConcurrentHashMap<String, Order> orders = new ConcurrentHashMap<>();
    private final RestaurantService restaurantService;
    private final DeliveryAgentService agentService;
    private final PaymentService paymentService;
    private final NotificationService notificationService;

    public OrderService(RestaurantService rs, DeliveryAgentService as,
                        PaymentService ps, NotificationService ns) {
        this.restaurantService = rs;
        this.agentService = as;
        this.paymentService = ps;
        this.notificationService = ns;
    }

    // ── 1. Customer places order ─────────
    public Order placeOrder(String customerId, String restaurantId,
                             List<OrderItem> items) {
        // Validate items + compute total
        long total = items.stream().mapToLong(i -> i.price() * i.quantity()).sum();

        // Process payment (hold funds)
        paymentService.holdFunds(customerId, total);

        Order order = new Order(customerId, restaurantId, items, total);
        orders.put(order.getOrderId(), order);

        notificationService.notifyRestaurant(restaurantId,
            "New order: " + order.getOrderId());
        return order;
    }

    // ── 2. Restaurant accepts ───────────
    public void restaurantAccept(String orderId) {
        Order order = getOrder(orderId);
        order.transitionTo(OrderStatus.CONFIRMED);
        order.transitionTo(OrderStatus.PREPARING);
        notificationService.notifyCustomer(order.getCustomerId(),
            "Your order is being prepared");
    }

    // ── 3. Restaurant marks ready → trigger agent dispatch ──
    public void markReady(String orderId) {
        Order order = getOrder(orderId);
        order.transitionTo(OrderStatus.READY);
        dispatchAgent(order);
    }

    // Internal: find and assign an agent
    private void dispatchAgent(Order order) {
        GeoLocation pickup = restaurantService.getLocation(order.getRestaurantId());
        Optional<DeliveryAgent> agentOpt =
            agentService.findAgentForOrder(pickup, order.getRejectedAgents());

        if (agentOpt.isEmpty()) {
            // No agent available — escalate / retry later
            notificationService.notifyCustomer(order.getCustomerId(),
                "Looking for a delivery agent...");
            // In production: retry after delay
            throw new NoAgentsAvailableException(order.getOrderId());
        }

        DeliveryAgent agent = agentOpt.get();
        agent.markBusy();
        order.assignAgent(agent.getAgentId());
        notificationService.notifyAgent(agent.getAgentId(),
            "New delivery: pick up at " + pickup);
    }

    // ── 4. Agent rejects → re-dispatch ──
    public void agentRejected(String orderId, String agentId) {
        Order order = getOrder(orderId);
        order.addRejectedAgent(agentId);
        DeliveryAgent agent = agentService.get(agentId);
        if (agent != null) agent.markAvailable();

        // Reset order to READY so we can reassign
        // (in production, transition through a REASSIGNING state)
        if (order.getRejectedAgents().size() >= 3) {
            // Escalate after 3 rejections
            notificationService.notifyCustomer(order.getCustomerId(),
                "Trouble finding a delivery agent — please wait");
        }
        dispatchAgent(order);
    }

    // ── 5. Agent picks up ─────────────
    public void agentPickup(String orderId, String agentId) {
        Order order = getOrder(orderId);
        if (!agentId.equals(order.getDeliveryAgentId()))
            throw new UnauthorizedActionException("Wrong agent");
        order.transitionTo(OrderStatus.PICKED_UP);
        notificationService.notifyCustomer(order.getCustomerId(),
            "Your order is on the way");
    }

    // ── 6. Agent delivers ─────────────
    public void agentDeliver(String orderId, String agentId) {
        Order order = getOrder(orderId);
        if (!agentId.equals(order.getDeliveryAgentId()))
            throw new UnauthorizedActionException("Wrong agent");

        order.transitionTo(OrderStatus.DELIVERED);

        // Side effects: free agent, release funds to restaurant
        DeliveryAgent agent = agentService.get(agentId);
        if (agent != null) agent.markAvailable();
        paymentService.releaseFundsToRestaurant(order.getRestaurantId(), order.getTotalAmount());

        notificationService.notifyCustomer(order.getCustomerId(), "Order delivered!");
    }

    // ── Cancellation (only before PICKED_UP) ──
    public void cancelOrder(String orderId) {
        Order order = getOrder(orderId);
        OrderStatus current = order.getStatus();
        if (current == OrderStatus.PICKED_UP || current == OrderStatus.DELIVERED)
            throw new CannotCancelException("Cannot cancel order in status " + current);

        order.transitionTo(OrderStatus.CANCELLED);

        // Side effects: free agent if assigned, refund customer
        if (order.getDeliveryAgentId() != null) {
            DeliveryAgent a = agentService.get(order.getDeliveryAgentId());
            if (a != null) a.markAvailable();
        }
        paymentService.refund(order.getCustomerId(), order.getTotalAmount());
        notificationService.notifyCustomer(order.getCustomerId(), "Order cancelled");
    }

    private Order getOrder(String orderId) {
        Order o = orders.get(orderId);
        if (o == null) throw new OrderNotFoundException(orderId);
        return o;
    }
}

interface PaymentService {
    void holdFunds(String customerId, long amount);
    void releaseFundsToRestaurant(String restaurantId, long amount);
    void refund(String customerId, long amount);
}

interface NotificationService {
    void notifyCustomer(String customerId, String message);
    void notifyRestaurant(String restaurantId, String message);
    void notifyAgent(String agentId, String message);
}
